// Placeholder models generated by code. Origin: bottom center (see mesher).
import { VoxelObject } from './voxel-object.js';
import { P, PALETTE } from './palette.js';
import { CFG } from './game/config.js';

export const VIAL_LAYERS = 9;
const CRUCIBLE_RADIUS = [2.5, 3.2, 3.8, 4.2, 4.4, 4.5, 4.5];

export function vialLayers(fill) {
  return fill > 0 ? Math.max(1, Math.ceil((fill / CFG.VIAL_CAPACITY) * VIAL_LAYERS)) : 0;
}

// 5x11x5 open-top glass vial; the liquid shows in a 3-wide window on the +z side.
export function vialModel(layers) {
  const o = VoxelObject.empty(5, 11, 5, PALETTE);
  for (let y = 0; y < 11; y++) {
    for (let z = 0; z < 5; z++) {
      for (let x = 0; x < 5; x++) {
        if ((x === 0 || x === 4) && (z === 0 || z === 4)) continue; // rounded corners
        const edge = x === 0 || x === 4 || z === 0 || z === 4;
        if (y > 0 && !edge) continue; // hollow, open top
        const window = z === 4 && x >= 1 && x <= 3 && y >= 1 && y <= VIAL_LAYERS;
        o.set(x, y, z, window ? (y <= layers ? P.MERCURY : P.GLASS_EMPTY) : P.GLASS);
      }
    }
  }
  return o;
}

export function leadColor(temp) {
  if (temp >= CFG.CRITICAL) return P.LEAD_CRIT;
  if (temp >= CFG.MELT) return P.LEAD_HOT;
  if (temp >= CFG.MELT / 2) return P.LEAD_WARM;
  return P.LEAD_COLD;
}

// Stack of colored layers inside the crucible, bottom to top.
export function crucibleContents(c) {
  switch (c.content) {
    case 'lead': {
      const stack = [{ color: leadColor(c.temp), layers: 2 }];
      const mercury = Math.round(c.mercury * 2);
      if (mercury > 0) stack.push({ color: P.MERCURY, layers: mercury });
      return stack;
    }
    case 'amalgam': return [{ color: c.quality >= 0.6 ? P.AMALGAM_GOOD : P.AMALGAM_POOR, layers: 3 }];
    case 'sludge': return [{ color: P.SLUDGE, layers: 3 }];
    case 'burnt': return [{ color: P.BURNT, layers: 1 }];
    default: return [];
  }
}

// 9x7x9 bowl, 1-voxel wall; interior layers y = 1..5.
export function crucibleModel(contents) {
  const o = VoxelObject.empty(9, 7, 9, PALETTE);
  const dist = (x, z) => Math.hypot(x - 4, z - 4);
  for (let y = 0; y < 7; y++) {
    for (let z = 0; z < 9; z++) {
      for (let x = 0; x < 9; x++) {
        const d = dist(x, z);
        if (d > CRUCIBLE_RADIUS[y]) continue;
        if (y === 0 || d > CRUCIBLE_RADIUS[y] - 1.2) o.set(x, y, z, P.CRUCIBLE);
      }
    }
  }
  let y = 1;
  for (const { color, layers } of contents) {
    for (let l = 0; l < layers && y <= 5; l++, y++) {
      for (let z = 0; z < 9; z++) {
        for (let x = 0; x < 9; x++) {
          if (dist(x, z) <= CRUCIBLE_RADIUS[y] - 1.2) o.set(x, y, z, color);
        }
      }
    }
  }
  return o;
}

export const FLAME_FRAMES = 4;
const FLAME_HEIGHT = [1, 2, 3, 2]; // voxels above the wick

// 9x7x9 tripod with a tea light inside and a ring on top (crucible sits on it); flame -1 = unlit.
export function standModel(flame) {
  const o = VoxelObject.empty(9, 7, 9, PALETTE);
  const dist = (x, z) => Math.hypot(x - 4, z - 4);
  for (let z = 0; z < 9; z++) {
    for (let x = 0; x < 9; x++) {
      const d = dist(x, z);
      if (d <= 4.2) o.set(x, 0, z, P.BRONZE);
      if (d > 1.6 && d <= 3.3) o.set(x, 6, z, P.BRONZE);
      if (d <= 2.2) for (let y = 1; y <= 2; y++) o.set(x, y, z, P.WAX);
    }
  }
  for (const [x, z] of [[2, 2], [6, 2], [2, 6], [6, 6]]) {
    for (let y = 1; y <= 5; y++) o.set(x, y, z, P.BRONZE);
  }
  o.set(4, 3, 4, P.BURNT); // wick
  if (flame >= 0) {
    for (let h = 1; h <= FLAME_HEIGHT[flame]; h++) {
      for (let z = 0; z < 9; z++) {
        for (let x = 0; x < 9; x++) {
          const radius = h === 1 ? 1.2 : 0.5;
          if (dist(x, z) <= radius) o.set(x, 3 + h, z, h === 1 ? P.FLAME_A : P.FLAME_B);
        }
      }
    }
  }
  return o;
}

// 1x7x1 match: wood y0..3, head y4, flame y5..6 when lit.
export function matchModel(lit) {
  const o = VoxelObject.empty(1, 7, 1, PALETTE);
  for (let y = 0; y <= 3; y++) o.set(0, y, 0, P.MATCH_WOOD);
  o.set(0, 4, 0, P.MATCH_HEAD);
  if (lit) {
    o.set(0, 5, 0, P.FLAME_A);
    o.set(0, 6, 0, P.FLAME_B);
  }
  return o;
}

// 6x3x4 matchbox with a striker strip on top; one red match head per match left.
export function matchboxModel(left) {
  const o = VoxelObject.empty(6, 3, 4, PALETTE);
  for (let z = 0; z < 4; z++) {
    for (let y = 0; y < 3; y++) {
      for (let x = 0; x < 6; x++) {
        const striker = y === 2 && x >= 1 && x <= 4 && z >= 1 && z <= 2;
        o.set(x, y, z, striker ? P.STRIKER : P.BOX);
      }
    }
  }
  for (let i = 0; i < left; i++) o.set(1 + i, 2, 3, P.MATCH_HEAD);
  return o;
}
